```js
// Currying: f(a, b, c) -> f(a)(b)(c)
const curry = fn => {
  const curried = (...args) =>
    args.length >= fn.length
      ? fn(...args)
      : (...next) => curried(...args, ...next);
  return curried;
};

const add3 = (a, b, c) => a + b + c;
const cAdd = curry(add3);
console.log(cAdd(1)(2)(3), cAdd(1, 2)(3), cAdd(1)(2, 3)); // 6 6 6

// Partial application: fix SOME arguments up front
const withSlash = (base, path) => `${base}/${path}`;
const api = withSlash.bind(null, 'https://api.example.com');
console.log(api('users')); // https://api.example.com/users

// Practical pipeline: reusable, testable units
const prop = key => obj => obj[key];
const byPrice = min => list => list.filter(p => p.price >= min);
const names = list => list.map(prop('name'));

const expensiveNames = products => names(byPrice(500)(products));
console.log(expensiveNames([{ name: 'M1', price: 100 }, { name: 'M2', price: 900 }]));
// ['M2']
```
Currying transforms an n-argument function into a chain of single-argument functions; partial application pre-fills some arguments and returns a function expecting the rest. Both enable config-then-execute patterns, point-free style and clean event-handler factories. Overdone, they hurt readability — curry only functions with stable leading arguments, and keep the data argument last.

```js
async function fetchJSON(url, options = {}) {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), 8000); // 8s timeout
  try {
    const res = await fetch(url, { ...options, signal: controller.signal });

    // fetch does NOT throw on HTTP errors (404/500) — check res.ok yourself
    if (!res.ok) {
      const body = await res.text().catch(() => '');
      throw new Error(`HTTP ${res.status} ${res.statusText}: ${body.slice(0, 100)}`);
    }
    return await res.json(); // throws SyntaxError if the body is not valid JSON
  } catch (err) {
    if (err.name === 'AbortError') throw new Error('Request timed out');
    throw err; // network failure (TypeError: Failed to fetch) or parse error
  } finally {
    clearTimeout(timeoutId);
  }
}

// Usage
fetchJSON('/api/items')
  .then(items => render(items))
  .catch(err => showError(err.message));
```
Critical facts: fetch only rejects on network failures — a 404 or 500 resolves normally, so you MUST check `response.ok` (true for status 200-299). Parse with `res.json()` or `res.text()`; both consume the body, which can be read only once. Add `AbortController` for timeouts and cancellation, and distinguish `err.name === 'AbortError'` from real failures.

