```js
const form = document.getElementById('signup');
const messages = {
  email: { valueMissing: 'Email is required.', typeMismatch: 'Enter a valid email address.' },
  pass: { valueMissing: 'Password is required.', tooShort: 'Use at least 8 characters.' }
};

function validate(input) {
  const err = input.closest('.field').querySelector('.error');
  if (input.validity.valid) {
    err.textContent = '';
    input.removeAttribute('aria-invalid');
    return true;
  }
  const map = messages[input.name];
  err.textContent = Object.keys(input.validity)
    .filter(k => input.validity[k] && map[k])
    .map(k => map[k])[0] || 'Invalid value.';
  input.setAttribute('aria-invalid', 'true');
  return false;
}

form.querySelectorAll('input').forEach(inp => {
  inp.addEventListener('blur', () => validate(inp));
  inp.addEventListener('input', () => {
    if (inp.getAttribute('aria-invalid')) validate(inp);
  });
});

form.addEventListener('submit', e => {
  e.preventDefault();
  const allValid = [...form.elements].filter(i => i.tagName === 'INPUT').map(validate).every(Boolean);
  if (allValid) console.log('Submitting:', Object.fromEntries(new FormData(form)));
});
```

Why it works: the built-in ValidityState API does the heavy lifting — novalidate turns off native popups so we can render our own inline messages, while input.validity flags (valueMissing, typeMismatch, tooShort) tell us exactly why a field failed. Each error small is an aria-live region so screen readers hear the message when it appears, and aria-invalid drives the red border via CSS. The UX flow follows best practice: validate on blur (not on every keystroke, which is noisy), then re-validate live only after a field has been marked invalid, so errors clear the moment the user fixes them.

