      <h3>SEO friendly</h3>
      <p>Clean structure that search engines understand.</p>
    </article>
    <article class="card">
      <h3>Blazing fast</h3>
      <p>Pages load in under a second on slow networks.</p>
    </article>
  </section>
  <script>
    const btn = document.querySelector('.menu-btn');
    const links = document.querySelector('.nav-links');
    btn.addEventListener('click', () => {
